import React, { useState, createContext, useContext, useEffect } from 'react';
import { HashRouter, Routes, Route, useLocation, Navigate } from 'react-router-dom';
import HomeScreen from './screens/HomeScreen';
import ProductDetailScreen from './screens/ProductDetailScreen';
import CartScreen from './screens/CartScreen';
import CheckoutFormScreen from './screens/CheckoutFormScreen';
import OrderConfirmationScreen from './screens/OrderConfirmationScreen';
import AdminDashboardScreen from './screens/AdminDashboardScreen';
import { CartItem, Product, Order } from './types';
import { PRODUCTS as FALLBACK_PRODUCTS } from './constants';
import { supabase } from './supabaseClient';

// --- Products Context ---
interface ProductsContextType {
  products: Product[];
  loading: boolean;
}
const ProductsContext = createContext<ProductsContextType | undefined>(undefined);

export const useProducts = () => {
    const context = useContext(ProductsContext);
    if (!context) throw new Error('useProducts must be used within a ProductsProvider');
    return context;
}

// --- Cart Context ---
interface CartContextType {
  cart: CartItem[];
  addToCart: (product: Product, quantity: number, extras: string[], selectedSauces: string[]) => void;
  removeFromCart: (productId: string) => void;
  updateQuantity: (productId: string, delta: number) => void;
  clearCart: () => void;
  cartTotal: number;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) throw new Error('useCart must be used within a CartProvider');
  return context;
};

// --- Orders Context ---
interface OrdersContextType {
  orders: Order[];
  addOrder: (customerData: { name: string; phone: string; address: string; notes: string }, cart: CartItem[], total: number) => Promise<void>;
  clearOrders: () => void;
  loading: boolean;
}

const OrdersContext = createContext<OrdersContextType | undefined>(undefined);

export const useOrders = () => {
  const context = useContext(OrdersContext);
  if (!context) throw new Error('useOrders must be used within an OrdersProvider');
  return context;
};

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const App: React.FC = () => {
  // State
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [productsLoading, setProductsLoading] = useState(true);
  const [ordersLoading, setOrdersLoading] = useState(true);

  // --- 1. Fetch Products from Supabase ---
  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const { data, error } = await supabase.from('products').select('*');
        if (error) {
            console.warn('Supabase fetch warning (using local data):', error.message);
            // Fallback to static constants if DB fails or is empty
            setProducts(FALLBACK_PRODUCTS);
        } else {
            if (data && data.length > 0) {
                // Map DB columns to our Typescript interface if names differ (snake_case to camelCase)
                // Assuming DB uses: id, name, description, price, image, category, rating, time, is_promo
                const mappedProducts: Product[] = data.map(p => ({
                    id: p.id,
                    name: p.name,
                    description: p.description,
                    price: p.price,
                    image: p.image,
                    category: p.category,
                    rating: p.rating,
                    time: p.time,
                    isPromo: p.is_promo
                }));
                setProducts(mappedProducts);
            } else {
                setProducts(FALLBACK_PRODUCTS);
            }
        }
      } catch (e: any) {
        console.warn('Supabase connection failed (using local data):', e.message || e);
        setProducts(FALLBACK_PRODUCTS);
      } finally {
        setProductsLoading(false);
      }
    };
    fetchProducts();
  }, []);

  // --- 2. Fetch Orders from Supabase ---
  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const { data, error } = await supabase
            .from('orders')
            .select('*')
            .order('created_at', { ascending: false });

        if (error) {
            console.warn('Supabase orders fetch warning:', error.message);
        } else if (data) {
            const mappedOrders: Order[] = data.map(o => ({
                id: o.id,
                customerName: o.customer_name,
                customerPhone: o.customer_phone,
                customerAddress: o.customer_address,
                additionalNotes: o.additional_notes,
                items: o.items, // JSONB
                total: o.total,
                date: o.date,
                status: o.status
            }));
            setOrders(mappedOrders);
        }
      } catch (e: any) {
         console.warn('Supabase orders connection failed:', e.message || e);
      } finally {
        setOrdersLoading(false);
      }
    };
    fetchOrders();
  }, []);

  // Cart Logic
  const addToCart = (product: Product, quantity: number, extras: string[], selectedSauces: string[]) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => 
          item.id === product.id 
            ? { 
                ...item, 
                quantity: item.quantity + quantity, 
                extras: [...new Set([...item.extras, ...extras])],
                selectedSauces: [...new Set([...item.selectedSauces, ...selectedSauces])]
              } 
            : item
        );
      }
      return [...prev, { ...product, quantity, selectedSauces, extras }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const clearCart = () => setCart([]);

  const cartTotal = cart.reduce((sum, item) => {
    let extraCost = 0;
    if(item.extras.includes('Queso Extra')) extraCost += 3000;
    if(item.extras.includes('Tocineta Crujiente')) extraCost += 4500;
    if(item.extras.includes('Huevo de Codorniz')) extraCost += 2000;
    return sum + ((item.price + extraCost) * item.quantity);
  }, 0);

  // Order Logic (Supabase Insert)
  const addOrder = async (customerData: { name: string; phone: string; address: string; notes: string }, cartItems: CartItem[], total: number) => {

    const simpleItems = cartItems.map(item => ({ 
        productId: item.id, 
        quantity: item.quantity,
        name: item.name, // Storing name in history is safer than just ID
        extras: item.extras,
        sauces: item.selectedSauces
    }));

    const newOrderData = {
      customer_name: customerData.name,
      customer_phone: customerData.phone,
      customer_address: customerData.address,
      additional_notes: customerData.notes,
      items: simpleItems,
      total: total,
      date: new Date().toISOString().split('T')[0],
      status: 'pending'
    };

    try {
        const { data, error } = await supabase.from('orders').insert([newOrderData]).select();

        if (error) {
            console.warn("Error inserting order (Database might not be connected):", error.message);
            // Do not alert the user, just log it. They will still go to WhatsApp.
        } else if (data) {
            // Optimistic update or refetch
            const mappedOrder: Order = {
                id: data[0].id,
                customerName: data[0].customer_name,
                customerPhone: data[0].customer_phone,
                customerAddress: data[0].customer_address,
                additionalNotes: data[0].additional_notes,
                items: data[0].items,
                total: data[0].total,
                date: data[0].date,
                status: data[0].status
            };
            setOrders(prev => [mappedOrder, ...prev]);
        }
    } catch (err: any) {
        console.warn("Supabase Insert Error:", err.message || err);
    }
  };

  const clearOrders = async () => {
    // Only clear local for safety, or implement delete all in supabase if authorized
    setOrders([]);
  };

  return (
    <ProductsContext.Provider value={{ products, loading: productsLoading }}>
        <OrdersContext.Provider value={{ orders, addOrder, clearOrders, loading: ordersLoading }}>
        <CartContext.Provider value={{ cart, addToCart, removeFromCart, updateQuantity, clearCart, cartTotal }}>
            <HashRouter>
            <ScrollToTop />
            <div className="mx-auto max-w-md bg-white min-h-screen shadow-2xl relative overflow-hidden">
                <Routes>
                <Route path="/" element={<HomeScreen />} />
                <Route path="/product/:id" element={<ProductDetailScreen />} />
                <Route path="/cart" element={<CartScreen />} />
                <Route path="/checkout" element={<CheckoutFormScreen />} />
                <Route path="/confirmation" element={<OrderConfirmationScreen />} />
                <Route path="/admin" element={<AdminDashboardScreen />} />
                <Route path="*" element={<Navigate to="/" />} />
                </Routes>
            </div>
            </HashRouter>
        </CartContext.Provider>
        </OrdersContext.Provider>
    </ProductsContext.Provider>
  );
};

