  useEffect(() => {
      setIsConfigured(isSupabaseConfigured());
  }, []);

  // Analytics Logic
  const analytics = useMemo(() => {
    // 1. Calculate Top Dishes
    const productCounts: { [key: string]: number } = {};
    orders.forEach(order => {
        if (Array.isArray(order.items)) {
            order.items.forEach(item => {
                productCounts[item.productId] = (productCounts[item.productId] || 0) + item.quantity;
            });
        }
    });

    const topProducts = Object.entries(productCounts)
        .map(([id, count]) => {
            const product = products.find(p => p.id === id);
            return product ? { ...product, count } : null;
        })
        .filter(p => p !== null)
        .sort((a, b) => b!.count - a!.count)
        .slice(0, 3);

    // 2. Calculate Loyal Customers
    const customerStats: { [key: string]: { name: string, visits: number, spent: number } } = {};

    orders.forEach(order => {
        const phone = order.customerPhone || 'Unknown';
        if (!customerStats[phone]) {
            customerStats[phone] = { name: order.customerName, visits: 0, spent: 0 };
        }
        customerStats[phone].visits += 1;
        customerStats[phone].spent += order.total;
    });

    const loyalCustomers = Object.values(customerStats)
        .sort((a, b) => b.visits - a.visits)
        .slice(0, 5);

    // 3. Totals
