import React, { useMemo, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useOrders, useProducts } from '../App';
import { updateSupabaseConfig, isSupabaseConfigured, getCurrentConfig } from '../supabaseClient';

const AdminDashboardScreen: React.FC = () => {
  const navigate = useNavigate();
  const { orders, clearOrders, loading: ordersLoading } = useOrders();
  const { products } = useProducts();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [pin, setPin] = useState('');
  const [showDeleteModal, setShowDeleteModal] = useState(false);

  // Config State
  const currentConfig = getCurrentConfig();
  const [showConfig, setShowConfig] = useState(false);
  const [sbUrl, setSbUrl] = useState(currentConfig.url);
  const [sbKey, setSbKey] = useState(currentConfig.key);
  const [isConfigured, setIsConfigured] = useState(false);

  // Admin PIN State
  const [newPin, setNewPin] = useState('');

  useEffect(() => {
      setIsConfigured(isSupabaseConfigured());
  }, []);

  // Analytics Logic
  const analytics = useMemo(() => {
    // 1. Calculate Top Dishes
    const productCounts: { [key: string]: number } = {};
    orders.forEach(order => {
        if (Array.isArray(order.items)) {
            order.items.forEach(item => {
                productCounts[item.productId] = (productCounts[item.productId] || 0) + item.quantity;
            });
        }
    });

    const topProducts = Object.entries(productCounts)
        .map(([id, count]) => {
            const product = products.find(p => p.id === id);
            return product ? { ...product, count } : null;
        })
        .filter(p => p !== null)
        .sort((a, b) => b!.count - a!.count)
        .slice(0, 3);

    // 2. Calculate Loyal Customers
    const customerStats: { [key: string]: { name: string, visits: number, spent: number } } = {};

    orders.forEach(order => {
        const phone = order.customerPhone || 'Unknown';
        if (!customerStats[phone]) {
            customerStats[phone] = { name: order.customerName, visits: 0, spent: 0 };
        }
        customerStats[phone].visits += 1;
        customerStats[phone].spent += order.total;
    });

    const loyalCustomers = Object.values(customerStats)
        .sort((a, b) => b.visits - a.visits)
        .slice(0, 5);

    // 3. Totals
    const totalSales = orders.reduce((acc, order) => acc + order.total, 0);
    const totalOrders = orders.length;

    return { topProducts, loyalCustomers, totalSales, totalOrders };
  }, [orders, products]);

  const handleLogin = (val: string) => {
     // Obtener PIN guardado o usar el defecto '2024'
     const storedPin = localStorage.getItem('potato_admin_pin') || '2024';

     if (val === storedPin) {
         setIsAuthenticated(true);
     } else {
         alert('PIN Incorrecto');
         setPin('');
     }
  };

  const handleChangePin = () => {
      if (newPin.length < 4) {
          alert('El PIN debe tener al menos 4 caracteres.');
          return;
      }
      localStorage.setItem('potato_admin_pin', newPin);
      alert('¡PIN actualizado correctamente!');
      setNewPin('');
  };

  const handleDeleteHistory = () => {
    clearOrders();
    setShowDeleteModal(false);
  };

  const handleSaveConfig = () => {
      if(!sbUrl || !sbKey) {
          alert("Por favor ingresa ambos campos");
          return;
      }
      updateSupabaseConfig(sbUrl, sbKey);
  };

  // Helper to get product names for the table
  const getProductNames = (items: any[]) => {
      if (!Array.isArray(items)) return ['Error en datos'];
      return items.map(item => {
          const product = products.find(p => p.id === item.productId);
          return product ? `${item.quantity}x ${product.name}` : `${item.quantity}x ${item.name || 'Producto'}`;
      });
  };

  if (!isAuthenticated) {
      return (
          <div className="flex flex-col items-center justify-center min-h-screen bg-background-dark p-6 text-white">
              <span className="material-symbols-outlined text-6xl text-primary mb-4">lock</span>
              <h1 className="text-2xl font-bold mb-2">Acceso Privado</h1>
              <p className="text-gray-400 mb-8 text-center">Datos sensibles del negocio.</p>

              <div className="w-full max-w-xs">
                  <input 
                    type="password" 
                    value={pin}
                    onChange={(e) => setPin(e.target.value)}
                    placeholder="Ingrese PIN de acceso"
                    className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-center text-xl tracking-widest mb-4 focus:ring-primary focus:border-primary placeholder:text-gray-500"
                    maxLength={10}
                  />
                  <button 
                    onClick={() => handleLogin(pin)}
                    className="w-full bg-primary text-background-dark font-bold py-4 rounded-xl hover:bg-yellow-400 transition-colors"
                  >
                      Desbloquear Dashboard
                  </button>
                  <button onClick={() => navigate('/')} className="w-full mt-4 text-gray-400 text-sm hover:text-white">
                      Volver a Inicio
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden shadow-2xl bg-gray-50">
