                >
                    Guardar y Conectar
                </button>
            </div>

            <div className="border-t border-gray-100 my-4"></div>

            {/* Change PIN Section */}
            <h3 className="font-bold text-[#181611] mb-2 flex items-center gap-2">
                <span className="material-symbols-outlined text-gray-400">lock_reset</span>
