const OrderConfirmationScreen: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { cart, cartTotal, clearCart } = useCart();
  const { addOrder } = useOrders();
  const [isProcessing, setIsProcessing] = useState(false);

  // Retrieve customer data passed from CheckoutForm
  const customerData = location.state?.customerData || { name: 'Cliente', phone: '', address: '', notes: '' };

  const deliveryFee = 3000;
  const finalTotal = cartTotal + deliveryFee;

  const handleSendOrder = () => {
      if (isProcessing) return;
      setIsProcessing(true);

      // 1. Guardar en base de datos Supabase en segundo plano (Fire and forget)
      const orderPromise = addOrder(
            { name: customerData.name, phone: customerData.phone, address: customerData.address, notes: customerData.notes }, 
            cart, 
            finalTotal
      ).catch(e => {
        console.error("Error saving order, proceeding to WhatsApp anyway", e);
      });

      // 2. Lógica de WhatsApp
      const phoneNumber = "573108912458"; // Número del comercio

      let message = `🍟 *NUEVO PEDIDO - POTATOES* 🍟\n\n`;
      message += `👤 *Cliente:* ${customerData.name}\n`;
      message += `📞 *Teléfono:* ${customerData.phone}\n`;
      message += `📍 *Dirección:* ${customerData.address}\n`;

      if (customerData.notes && customerData.notes.trim() !== '') {
        message += `📝 *Nota:* ${customerData.notes}\n`;
      }

      message += `\n🛒 *DETALLE DEL PEDIDO:*\n`;

      cart.forEach((item) => {
        message += `▪️ *${item.quantity}x ${item.name}*\n`;

        if (item.selectedSauces && item.selectedSauces.length > 0) {
          message += `   └ 🥣 Salsas: ${item.selectedSauces.join(', ')}\n`;
        }

        if (item.extras && item.extras.length > 0) {
          message += `   └ 🧀 Extras: ${item.extras.join(', ')}\n`;
        }
      });

      message += `\n--------------------------------\n`;
      message += `💰 *Subtotal:* $${cartTotal.toLocaleString()}\n`;
      message += `🛵 *Domicilio:* $${deliveryFee.toLocaleString()}\n`;
      message += `💵 *TOTAL A PAGAR: $${finalTotal.toLocaleString()}*\n`;

      // Usamos api.whatsapp.com que es más robusto para web y evita redirecciones fallidas de wa.me
      const whatsappURL = `https://api.whatsapp.com/send?phone=${phoneNumber}&text=${encodeURIComponent(message)}`;

      // 3. Limpiar carrito
      clearCart();

      // 4. Abrir WhatsApp en nueva pestaña
      window.open(whatsappURL, '_blank');

      // 5. Redirigir al inicio
      setTimeout(() => {
        navigate('/');
      }, 1000);
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden pb-24 bg-background-light">
      <header className="sticky top-0 z-50 bg-background-light/95 backdrop-blur-sm p-4 pb-2">
        <div className="flex items-center justify-between">
          <button onClick={() => navigate(-1)} className="flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-black/5 transition-colors">
            <span className="material-symbols-outlined text-[#181611]" style={{fontSize: '24px'}}>arrow_back</span>
          </button>
          <h2 className="text-[#181611] text-lg font-bold leading-tight tracking-[-0.015em] flex-1 text-center pr-12">Confirmar Pedido</h2>
        </div>
      </header>

      <main className="flex-1 px-4 pt-2">
        <section className="mb-6">
          <h2 className="text-[#181611] tracking-tight text-[22px] font-bold leading-tight text-left pb-4 pt-2">Resumen del Pedido</h2>
          <div className="bg-white rounded-lg p-5 shadow-sm border border-black/5">
            <div className="flex flex-col gap-4 mb-4">
              {cart.map((item, index) => (
                <div key={index} className="flex justify-between items-start gap-x-4">
                  <div className="flex gap-3">
                    <div className="bg-primary/20 flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-black font-bold text-sm">{item.quantity}x</div>
                    <div className="min-w-0">
                      <p className="text-[#181611] text-base font-semibold leading-normal">{item.name}</p>
                      {item.extras.length > 0 && <p className="text-[#8a8060] text-sm font-normal leading-normal">+ {item.extras.join(', ')}</p>}
                      {item.selectedSauces.length > 0 && <p className="text-primary/90 text-sm font-medium leading-normal">Salsas: {item.selectedSauces.join(', ')}</p>}
                      {item.extras.length === 0 && item.selectedSauces.length === 0 && <p className="text-[#8a8060] text-sm font-normal leading-normal">Normal</p>}
                    </div>
                  </div>
                  <p className="text-[#181611] text-base font-semibold leading-normal text-right whitespace-nowrap">${item.price.toLocaleString()}</p>
                </div>
              ))}
            </div>

            <div className="h-px bg-gray-100 my-4 border-dashed border-b border-gray-200"></div>

            <div className="space-y-2">
              <div className="flex justify-between gap-x-6">
                <p className="text-[#8a8060] text-sm font-normal">Subtotal</p>
                <p className="text-[#181611] text-sm font-medium">${cartTotal.toLocaleString()}</p>
              </div>
              <div className="flex justify-between gap-x-6">
                <p className="text-[#8a8060] text-sm font-normal">Envío</p>
                <p className="text-[#181611] text-sm font-medium">${deliveryFee.toLocaleString()}</p>
              </div>
              <div className="flex justify-between gap-x-6 pt-2 items-center">
                <p className="text-[#181611] text-lg font-bold">Total a Pagar</p>
