              <p className="text-lg font-bold leading-tight tracking-[-0.015em] text-[#181611]">{product.name}</p>
              <p className="text-gray-500 text-sm font-normal leading-normal line-clamp-2">
                {product.description}
              </p>
              <div className="flex items-end gap-3 justify-between mt-3">
                <p className="text-xl font-extrabold text-primary">${product.price.toLocaleString()}</p>
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    navigate(`/product/${product.id}`);
                  }}
                  className="flex cursor-pointer items-center justify-center overflow-hidden rounded-full h-10 px-6 bg-primary text-background-dark hover:bg-yellow-400 transition-colors shadow-lg shadow-yellow-500/20 active:scale-95"
                >
                  <span className="text-sm font-bold mr-1">Agregar</span>
                  <span className="material-symbols-outlined text-[18px]">add</span>
                </button>
              </div>
            </div>
          </div>
        ))
        ) : (
             <div className="p-8 text-center text-gray-500">
                No hay productos disponibles.
             </div>
        )}
      </section>

      {/* Bottom Nav */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 pb-safe pt-2 px-6 shadow-[0_-5px_10px_rgba(0,0,0,0.02)] z-50 max-w-md mx-auto">
        <div className="flex justify-around items-center h-16">
          <button className="flex flex-col items-center gap-1 w-12 text-primary">
            <span className="material-symbols-outlined filled">home</span>
            <span className="text-[10px] font-bold">Inicio</span>
          </button>
          <button onClick={() => navigate('/cart')} className="flex flex-col items-center gap-1 w-12 text-gray-400 hover:text-primary transition-colors">
            <span className="material-symbols-outlined">receipt_long</span>
            <span className="text-[10px] font-medium">Pedidos</span>
          </button>
          <button className="flex flex-col items-center gap-1 w-12 text-gray-400 hover:text-primary transition-colors">
            <span className="material-symbols-outlined">favorite</span>
            <span className="text-[10px] font-medium">Favs</span>
          </button>
          <button onClick={() => navigate('/admin')} className="flex flex-col items-center gap-1 w-12 text-gray-400 hover:text-primary transition-colors">
            <span className="material-symbols-outlined">admin_panel_settings</span>
            <span className="text-[10px] font-medium">Admin</span>
          </button>
        </div>
      </nav>
    </div>
  );
};

export default HomeScreen;

import React, { useMemo, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useOrders, useProducts } from '../App';
import { updateSupabaseConfig, isSupabaseConfigured, getCurrentConfig } from '../supabaseClient';
import { BRAND_CONFIG } from '../constants';

const AdminDashboardScreen: React.FC = () => {
  const navigate = useNavigate();
  const { orders, clearOrders, loading: ordersLoading } = useOrders();
  const { products } = useProducts();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [pin, setPin] = useState('');
  const [showDeleteModal, setShowDeleteModal] = useState(false);

  // Config State
  const currentConfig = getCurrentConfig();
  const [showConfig, setShowConfig] = useState(false);
  const [sbUrl, setSbUrl] = useState(currentConfig.url);
  const [sbKey, setSbKey] = useState(currentConfig.key);
  const [isConfigured, setIsConfigured] = useState(false);

  // Admin PIN State
  const [newPin, setNewPin] = useState('');

  useEffect(() => {
      setIsConfigured(isSupabaseConfigured());
  }, []);

  // Analytics Logic
  const analytics = useMemo(() => {
    // 1. Calculate Top Dishes
    const productCounts: { [key: string]: number } = {};
    orders.forEach(order => {
        if (Array.isArray(order.items)) {
            order.items.forEach(item => {
                productCounts[item.productId] = (productCounts[item.productId] || 0) + item.quantity;
            });
        }
    });

    const topProducts = Object.entries(productCounts)
        .map(([id, count]) => {
            const product = products.find(p => p.id === id);
            return product ? { ...product, count } : null;
        })
        .filter(p => p !== null)
        .sort((a, b) => b!.count - a!.count)
        .slice(0, 3);

    // 2. Calculate Loyal Customers
    const customerStats: { [key: string]: { name: string, visits: number, spent: number } } = {};

    orders.forEach(order => {
        const phone = order.customerPhone || 'Unknown';
        if (!customerStats[phone]) {
            customerStats[phone] = { name: order.customerName, visits: 0, spent: 0 };
        }
        customerStats[phone].visits += 1;
        customerStats[phone].spent += order.total;
    });

    const loyalCustomers = Object.values(customerStats)
        .sort((a, b) => b.visits - a.visits)
        .slice(0, 5);

    // 3. Totals
    const totalSales = orders.reduce((acc, order) => acc + order.total, 0);
    const totalOrders = orders.length;

    return { topProducts, loyalCustomers, totalSales, totalOrders };
  }, [orders, products]);

  const handleLogin = (val: string) => {
     // Obtener PIN guardado o usar el defecto '2024'
     const storedPin = localStorage.getItem('potato_admin_pin') || '2024';

     if (val === storedPin) {
         setIsAuthenticated(true);
     } else {
         alert('PIN Incorrecto');
         setPin('');
     }
  };

  const handleChangePin = () => {
      if (newPin.length < 4) {
          alert('El PIN debe tener al menos 4 caracteres.');
          return;
      }
      localStorage.setItem('potato_admin_pin', newPin);
      alert('¡PIN actualizado correctamente!');
      setNewPin('');
  };

  const handleDeleteHistory = () => {
    clearOrders();
    setShowDeleteModal(false);
  };

  const handleSaveConfig = () => {
      if(!sbUrl || !sbKey) {
          alert("Por favor ingresa ambos campos");
          return;
      }
      updateSupabaseConfig(sbUrl, sbKey);
  };

  // Helper to get product names for the table
  const getProductNames = (items: any[]) => {
      if (!Array.isArray(items)) return ['Error en datos'];
      return items.map(item => {
          const product = products.find(p => p.id === item.productId);
          return product ? `${item.quantity}x ${product.name}` : `${item.quantity}x ${item.name || 'Producto'}`;
      });
  };

  if (!isAuthenticated) {
      return (
          <div className="flex flex-col items-center justify-center min-h-screen bg-background-dark p-6 text-white">
              <span className="material-symbols-outlined text-6xl text-primary mb-4">lock</span>
              <h1 className="text-2xl font-bold mb-2">Acceso Privado</h1>
              <p className="text-gray-400 mb-8 text-center">Datos sensibles del negocio.</p>

              <div className="w-full max-w-xs">
                  <input 
                    type="password" 
                    value={pin}
                    onChange={(e) => setPin(e.target.value)}
                    placeholder="Ingrese PIN de acceso"
                    className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-center text-xl tracking-widest mb-4 focus:ring-primary focus:border-primary placeholder:text-gray-500"
                    maxLength={10}
                  />
                  <button 
                    onClick={() => handleLogin(pin)}
                    className="w-full bg-primary text-background-dark font-bold py-4 rounded-xl hover:bg-yellow-400 transition-colors"
                  >
                      Desbloquear Dashboard
                  </button>
                  <button onClick={() => navigate('/')} className="w-full mt-4 text-gray-400 text-sm hover:text-white">
                      Volver a Inicio
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden shadow-2xl bg-gray-50">
      {/* Header */}
      <header className="flex items-center p-4 pt-6 pb-4 justify-between sticky top-0 z-20 bg-white shadow-sm">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full overflow-hidden border border-gray-200 bg-white">
            <img 
              src={BRAND_CONFIG.LOGO_URL} 
              alt="Logo" 
              className="h-full w-full object-cover p-1" 
            />
          </div>
          <div>
            <h2 className="text-[#181611] text-lg font-bold leading-tight">Admin Dashboard</h2>
            <div className="flex items-center gap-1">
                <div className={`w-2 h-2 rounded-full ${isConfigured ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                <p className="text-xs font-medium text-gray-500">
                {isConfigured ? 'Base de Datos Conectada' : 'Modo Local'}
                </p>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button onClick={() => setShowConfig(!showConfig)} className={`flex items-center justify-center h-9 w-9 rounded-full ${showConfig ? 'bg-primary text-black' : 'bg-gray-100 text-gray-600'}`}>
                <span className="material-symbols-outlined text-lg">settings</span>
            </button>
            <button onClick={() => setIsAuthenticated(false)} className="text-sm font-bold text-gray-400 hover:text-red-500">
                Salir
            </button>
        </div>
      </header>

      {/* Config Section */}
      {showConfig && (
        <div className="bg-white border-b border-gray-200 p-4 animate-[slideDown_0.3s_ease-out]">

            {/* Supabase Config */}
            <h3 className="font-bold text-[#181611] mb-2 flex items-center gap-2">
                <span className="material-symbols-outlined text-gray-400">database</span>
                Conexión Base de Datos
            </h3>
            <p className="text-xs text-gray-500 mb-4">Ingresa las credenciales de Supabase para sincronizar.</p>

            <div className="space-y-3 mb-6">
                <div>
                    <label className="text-xs font-bold text-gray-700 block mb-1">Project URL</label>
                    <input 
                        type="text" 
                        value={sbUrl}
                        onChange={(e) => setSbUrl(e.target.value)}
                        placeholder="https://xyz.supabase.co"
                        className="w-full text-sm rounded-lg border-gray-300 focus:border-primary focus:ring-primary"
                    />
                </div>
                <div>
                    <label className="text-xs font-bold text-gray-700 block mb-1">API Key (Anon/Public)</label>
                    <input 
                        type="password" 
                        value={sbKey}
                        onChange={(e) => setSbKey(e.target.value)}
                        placeholder="eyJhbGciOiJIUzI1NiIsInR5..."
                        className="w-full text-sm rounded-lg border-gray-300 focus:border-primary focus:ring-primary"
                    />
                </div>
                <button 
                    onClick={handleSaveConfig}
                    className="w-full bg-black text-white py-3 rounded-lg font-bold text-sm hover:bg-gray-800 transition-colors"
                >
                    Guardar y Conectar
                </button>
            </div>

            <div className="border-t border-gray-100 my-4"></div>

            {/* Change PIN Section */}
            <h3 className="font-bold text-[#181611] mb-2 flex items-center gap-2">
                <span className="material-symbols-outlined text-gray-400">lock_reset</span>
                Seguridad
            </h3>
            <div className="space-y-3">
                <div>
                    <label className="text-xs font-bold text-gray-700 block mb-1">Cambiar PIN de Acceso</label>
                    <div className="flex gap-2">
                        <input 
                            type="password" 
                            value={newPin}
                            onChange={(e) => setNewPin(e.target.value)}
                            placeholder="Nuevo PIN"
                            className="flex-1 text-sm rounded-lg border-gray-300 focus:border-primary focus:ring-primary"
                            maxLength={10}
                        />
                        <button 
                            onClick={handleChangePin}
                            className="bg-primary text-black px-4 py-2 rounded-lg font-bold text-sm hover:bg-yellow-500 transition-colors"
                        >
                            Actualizar
                        </button>
                    </div>
                    <p className="text-[10px] text-gray-400 mt-1">El PIN por defecto es 2024.</p>
                </div>
            </div>

        </div>
      )}

      {/* Main Stats Grid */}
      <div className="grid grid-cols-2 gap-3 p-4">
        {/* Total Sales Card */}
        <div className="col-span-2 bg-gradient-to-br from-primary to-yellow-500 rounded-2xl p-5 text-white shadow-lg relative overflow-hidden">
            <div className="relative z-10">
                <p className="text-sm font-medium opacity-90">Ingresos Totales</p>
                <h3 className="text-4xl font-extrabold mt-1">${analytics.totalSales.toLocaleString()}</h3>
                <div className="mt-3 inline-flex items-center gap-1 bg-white/20 px-2 py-1 rounded-lg text-xs font-semibold backdrop-blur-sm">
                    <span className="material-symbols-outlined text-[14px]">update</span>
                    <span>Actualizado ahora</span>
                </div>
            </div>
            <span className="material-symbols-outlined absolute -right-4 -bottom-4 text-9xl opacity-20 text-white">savings</span>
        </div>

        {/* Order Count */}
        <div className="bg-white rounded-2xl p-4 shadow-sm border border-gray-100 flex flex-col justify-center items-center gap-1">
             <div className="h-10 w-10 rounded-full bg-blue-50 flex items-center justify-center text-blue-600 mb-1">
                <span className="material-symbols-outlined">receipt</span>
             </div>
             <p className="text-2xl font-bold text-[#181611]">{analytics.totalOrders}</p>
             <p className="text-xs text-gray-500">Pedidos Totales</p>
        </div>

        {/* Unique Customers */}
        <div className="bg-white rounded-2xl p-4 shadow-sm border border-gray-100 flex flex-col justify-center items-center gap-1">
             <div className="h-10 w-10 rounded-full bg-purple-50 flex items-center justify-center text-purple-600 mb-1">
                <span className="material-symbols-outlined">groups</span>
             </div>
             <p className="text-2xl font-bold text-[#181611]">{analytics.loyalCustomers.length}</p>
             <p className="text-xs text-gray-500">Clientes Únicos</p>
        </div>
      </div>

      <div className="px-4 pb-24 space-y-6">

        {/* Top Products Section */}
        <section>
            <div className="flex items-center justify-between mb-3">
                <h3 className="text-[#181611] font-bold text-lg flex items-center gap-2">
                    <span className="material-symbols-outlined text-primary">trophy</span>
                    Productos Estrella
                </h3>
            </div>
            <div className="bg-white rounded-2xl p-1 shadow-sm border border-gray-100">
                {analytics.topProducts.map((product, idx) => (
                    <div key={product!.id} className={`flex items-center gap-3 p-3 ${idx !== analytics.topProducts.length -1 ? 'border-b border-gray-50' : ''}`}>
                        <div className="relative h-12 w-12 rounded-lg overflow-hidden shrink-0">
                            <img src={product!.image} className="w-full h-full object-cover" alt="" />
                            <div className="absolute inset-0 bg-black/20 flex items-center justify-center text-white font-bold text-sm">#{idx + 1}</div>
                        </div>
                        <div className="flex-1">
                            <p className="text-sm font-bold text-[#181611]">{product!.name}</p>
                            <div className="w-full bg-gray-100 rounded-full h-1.5 mt-2 overflow-hidden">
                                <div className="bg-primary h-full rounded-full" style={{width: `${(product!.count / analytics.totalOrders) * 100}%`}}></div>
                            </div>
                        </div>
                        <div className="text-right">
                            <span className="block text-lg font-bold text-[#181611]">{product!.count}</span>
                            <span className="text-[10px] text-gray-400">Unds</span>
                        </div>
                    </div>
                ))}
            </div>
        </section>

        {/* Loyal Customers Section */}
        <section>
            <h3 className="text-[#181611] font-bold text-lg mb-3 flex items-center gap-2">
                <span className="material-symbols-outlined text-primary">diamond</span>
                Top Clientes (Fidelidad)
            </h3>
            <div className="flex gap-4 overflow-x-auto no-scrollbar pb-2">
                {analytics.loyalCustomers.map((customer, idx) => (
                    <div key={idx} className="bg-white min-w-[140px] rounded-xl p-4 shadow-sm border border-gray-100 flex flex-col items-center gap-2 text-center relative overflow-hidden">
                        {idx === 0 && <div className="absolute top-0 right-0 bg-yellow-400 text-[9px] font-bold px-2 py-0.5 rounded-bl-lg text-[#181611]">MVP</div>}
                        <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-lg uppercase">
                            {customer.name.charAt(0)}
                        </div>
                        <div>
                            <p className="text-sm font-bold text-[#181611] truncate w-28">{customer.name}</p>
                            <p className="text-xs text-gray-500">{customer.visits} Compras</p>
                        </div>
                        <div className="mt-1 w-full pt-2 border-t border-gray-50">
                            <p className="text-xs font-bold text-green-600">${customer.spent.toLocaleString()}</p>
                        </div>
                    </div>
                ))}
            </div>
        </section>

        {/* Recent Orders Log */}
        <section>
            <h3 className="text-[#181611] font-bold text-lg mb-3">Historial Completo</h3>
            <div className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100">
                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm text-gray-500">
                        <thead className="bg-gray-50 text-xs uppercase text-gray-700">
                            <tr>
                                <th className="px-4 py-3">Cliente</th>
                                <th className="px-4 py-3">Pedido</th>
                                <th className="px-4 py-3 text-right">Total</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {orders.map((order) => (
                                <tr key={order.id} className="hover:bg-gray-50">
                                    <td className="px-4 py-3 font-medium text-[#181611] align-top">
                                        <div className="truncate max-w-[100px]" title={order.customerName}>{order.customerName}</div>
                                        <div className="text-[10px] text-gray-400 font-normal">{order.date}</div>
                                    </td>
                                    <td className="px-4 py-3 align-top">
                                        <div className="flex flex-col gap-1">
                                            {getProductNames(order.items).map((itemName, i) => (
                                                <span key={i} className="text-xs text-gray-600 bg-gray-100 px-2 py-0.5 rounded-md inline-block whitespace-nowrap">
                                                    {itemName}
                                                </span>
                                            ))}
                                        </div>
                                    </td>
                                    <td className="px-4 py-3 font-bold text-[#181611] text-right align-top">
                                        ${order.total.toLocaleString()}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                {orders.length === 0 && (
                    <div className="p-8 text-center text-gray-400">
                        No hay pedidos registrados aún.
                    </div>
                )}
            </div>
        </section>

        {/* Danger Zone */}
        <section className="pt-4 border-t border-gray-200">
            <h3 className="text-red-600 font-bold text-sm mb-2 uppercase tracking-wide">Zona de Peligro</h3>
            <button 
                onClick={() => setShowDeleteModal(true)}
                className="w-full flex items-center justify-center gap-2 bg-red-50 text-red-600 p-4 rounded-xl border border-red-100 font-bold hover:bg-red-100 transition-colors"
            >
                <span className="material-symbols-outlined">delete_forever</span>
                Eliminar Historial de Pedidos
            </button>
        </section>

      </div>

      {/* Confirmation Modal */}
      {showDeleteModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
              <div className="bg-white rounded-2xl shadow-2xl p-6 max-w-sm w-full animate-[scaleIn_0.2s_ease-out]">
                  <div className="flex flex-col items-center text-center gap-4">
                      <div className="h-16 w-16 rounded-full bg-red-100 flex items-center justify-center text-red-500">
                          <span className="material-symbols-outlined text-3xl">warning</span>
                      </div>
                      <div>
                          <h3 className="text-xl font-bold text-[#181611]">¿Estás seguro?</h3>
                          <p className="text-gray-500 text-sm mt-2">
                              Esta acción eliminará localmente el historial. Para borrar la base de datos, usa la consola de Supabase.
                          </p>
                      </div>
                      <div className="flex gap-3 w-full mt-2">
                          <button 
                              onClick={() => setShowDeleteModal(false)}
                              className="flex-1 py-3 rounded-xl border border-gray-200 font-bold text-gray-600 hover:bg-gray-50 transition-colors"
                          >
                              Cancelar
                          </button>
                          <button 
                              onClick={handleDeleteHistory}
                              className="flex-1 py-3 rounded-xl bg-red-500 text-white font-bold hover:bg-red-600 transition-colors shadow-lg shadow-red-500/30"
                          >
                              Sí, Limpiar Vista
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default AdminDashboardScreen;
